  result['basic-actions'] = detection(basicFound.length ? 'detected' : 'missing', `${basicFound.length}/${basic.length} common movement actions were detected. Human review still determines whether they are correct.`, [character.air]);
  const gethits = [5000, 5001, 5002, 5010, 5011, 5012, 5020, 5030, 5035, 5040, 5050, 5060, 5070, 5080, 5100, 5110, 5120, 5150, 5160, 5170, 5180, 5200, 5210], hitFound = gethits.filter((number) => actions.has(number));
