function ticket(t){const done=t.subtasks.filter(x=>x.done).length,total=t.subtasks.length,parent=data.ticketBoard.tickets.find(x=>x.id===t.parentId),children=data.ticketBoard.tickets.filter(x=>!x.archived&&x.parentId===t.id),childrenDone=children.filter(x=>x.column==='done').length,parts=t.type==='Epic'?children.length:total,complete=t.type==='Epic'?childrenDone:done;return '<article class="ticket '+(t.column==='done'?'done':'')+'"><h3>'+esc(t.title)+'</h3>'+(parent?'<div class="meta">↳ '+esc(parent.id)+' · '+esc(parent.title)+'</div>':'')+'<div class="meta"><b>'+esc(t.id)+'</b> · '+esc(t.type)+(t.character?' · '+esc(t.character):'')+(t.assignedTo?' · '+esc(t.assignedTo):' · unassigned')+'</div>'+(t.description?'<div class="ticket-description">'+esc(t.description)+'</div>':'')+'<div class="progress"><span style="width:'+(parts?Math.round(complete/parts*100):0)+'%"></span></div><div class="meta">'+(t.type==='Epic'?(childrenDone+'/'+children.length+' child tickets'):(done+'/'+total+' tasks'))+'</div><ul class="subtasks">'+t.subtasks.map(s=>'<li><label><input type="checkbox" data-ticket-task="'+esc(t.id)+'" data-task="'+esc(s.id)+'" '+(s.done?'checked':'')+'><span>'+esc(s.title)+(s.assignedTo?' · '+esc(s.assignedTo):'')+'</span></label></li>').join('')+'</ul>'+(children.length?'<details><summary>Child tickets ('+children.length+')</summary>'+children.map(c=>'<div>• <b>'+esc(c.id)+'</b> '+esc(c.title)+' — '+esc(c.column)+'</div>').join('')+'</details>':'')+(t.comments.length?'<details><summary>Discussion ('+t.comments.length+')</summary><div class="comments">'+t.comments.map(c=>'<div><b>'+esc(c.author)+':</b> '+esc(c.text)+'</div>').join('')+'</div></details>':'')+'<div class="actions"><select data-ticket-column="'+esc(t.id)+'">'+data.ticketColumns.map(c=>'<option value="'+c.id+'" '+(c.id===t.column?'selected':'')+'>'+esc(c.label)+'</option>').join('')+'</select>'+(t.type==='Epic'?'<button data-ticket-child="'+esc(t.id)+'">Child ticket…</button>':'<button data-ticket-task-add="'+esc(t.id)+'">Task…</button>')+'<button data-ticket-assign="'+esc(t.id)+'">Assign…</button><button data-ticket-comment="'+esc(t.id)+'">Comment…</button><button data-ticket-archive="'+esc(t.id)+'">Archive</button></div></article>'}
function wireTickets(){for(const s of document.querySelectorAll('[data-ticket-column]')){const t=data.ticketBoard.tickets.find(x=>x.id===s.dataset.ticketColumn),watching=t?.watchers.some(x=>x.toLowerCase()===data.actor.toLowerCase());s.parentElement.insertAdjacentHTML('beforeend','<button data-ticket-watch="'+esc(s.dataset.ticketColumn)+'">'+(watching?'Unwatch':'Watch')+' ('+(t?.watchers.length||0)+')</button>');s.onchange=()=>vscode.postMessage({type:'ticketColumn',id:s.dataset.ticketColumn,column:s.value})}for(const b of document.querySelectorAll('[data-ticket-watch]'))b.onclick=()=>vscode.postMessage({type:'ticketWatch',id:b.dataset.ticketWatch});for(const b of document.querySelectorAll('[data-ticket-child]'))b.onclick=()=>vscode.postMessage({type:'ticketChild',id:b.dataset.ticketChild});for(const b of document.querySelectorAll('[data-ticket-assign]'))b.onclick=()=>vscode.postMessage({type:'ticketAssign',id:b.dataset.ticketAssign});for(const b of document.querySelectorAll('[data-ticket-task-add]'))b.onclick=()=>vscode.postMessage({type:'ticketAddTask',id:b.dataset.ticketTaskAdd});for(const b of document.querySelectorAll('[data-ticket-comment]'))b.onclick=()=>vscode.postMessage({type:'ticketComment',id:b.dataset.ticketComment});for(const b of document.querySelectorAll('[data-ticket-archive]'))b.onclick=()=>vscode.postMessage({type:'ticketArchive',id:b.dataset.ticketArchive});for(const c of document.querySelectorAll('[data-ticket-task]'))c.onchange=()=>vscode.postMessage({type:'ticketTask',id:c.dataset.ticketTask,taskId:c.dataset.task,done:c.checked})}
function reportCard(r){return '<article class="step"><h3>'+esc(r.title)+'</h3><div class="meta"><b>'+esc(r.id)+'</b> · '+esc(r.status)+' · reported by '+esc(r.reporter||'unknown')+'</div><div class="ticket-description">'+esc(r.body)+'</div>'+(r.attachments.length?'<div class="meta">Attachments: '+r.attachments.map(esc).join(', ')+'</div>':'')+(r.decision?'<div class="note"><b>Decision:</b> '+esc(r.decision)+'</div>':'')+(r.status==='pending'?'<div class="actions"><button data-report-accept="'+esc(r.id)+'">Accept as ticket…</button><button data-report-reject="'+esc(r.id)+'">Reject…</button></div>':'')+'</article>'}
function memberCard(m){return '<article class="step"><h3>'+esc(m.name)+' <span class="badge">@'+esc(m.handle)+'</span></h3><div>'+m.roles.map(r=>'<span class="badge">'+esc(r)+'</span>').join(' ')+'</div><div class="meta">'+(m.active?'Active':'Inactive')+'</div><div class="actions"><button data-member-edit="'+esc(m.id)+'">Edit roles…</button><button data-member-active="'+esc(m.id)+'">'+(m.active?'Mark inactive':'Reactivate')+'</button></div></article>'}
function noticeCard(n){const t=data.ticketBoard.tickets.find(x=>x.id===n.ticketId);return '<article class="step"><h3>'+esc(n.ticketId)+(t?' · '+esc(t.title):'')+'</h3><div>'+esc(n.text)+'</div><div class="meta">'+esc(n.time)+'</div></article>'}
function issueDetails(item){return '<details><summary>Issue details</summary>'+[['Project',item.project||data.ticketBoard.project],['Work project ID',item.workProjectId],['Game project ID',item.gameProjectId],['Severity',item.severity],['IKEMaker version',item.toolVersion],['Item type',item.itemType],['Item name',item.itemName],['Item/content version',item.contentVersion],['Game/project profile',item.profile],['Screen/viewer',item.screen],['New use-case scenario',item.useCase],['Other build',item.build],['Steps to reproduce',item.steps],['Expected result',item.expected],['Actual result',item.actual],['Attachments',(item.attachments||[]).join(', ')]].filter(pair=>pair[1]).map(pair=>'<div class="note"><b>'+esc(pair[0])+':</b> '+esc(pair[1])+'</div>').join('')+'</details>'}
function issueForm(){
  const c=data.reportContext||{},field=(name,label,value='')=>'<label>'+label+'<input name="'+name+'" value="'+esc(value)+'" style="display:block;width:100%"></label>',area=(name,label,required=false)=>'<label style="display:block;margin:8px 0">'+label+'<textarea name="'+name+'" rows="3" style="display:block;width:100%;resize:vertical" '+(required?'required':'')+'></textarea></label>';
  return '<details class="step"><summary><b>Log a project issue or feedback</b></summary><form id="issueForm"><p>Project: <b>'+esc(data.assignedWorkProject?.name||data.ticketBoard.project)+'</b>. Saved to the shared game board; each issue keeps its work-project identity. IKEMaker '+esc(c.toolVersion||'Unknown')+' is recorded automatically.</p><label>Title (required)<input name="title" required style="display:block;width:100%"></label>'+area('body','What happened? (required)',true)+area('expected','What I would have liked to happen')+area('useCase','New use-case scenario (optional)')+area('attachments','Screenshots, mockups, logs or file references (optional, one path or link per line)')+'<details class="step"><summary>Context and reproduction details</summary><p class="muted">Current character and workflow are prefilled. Change these when reporting a different item. Choose a definition to read its declared name/version, or enter details manually; Unknown is accepted.</p><div class="steps"><label>Item type<select id="issueItemType" name="itemType" style="display:block;width:100%">'+(data.itemTypes||[]).map(x=>'<option '+(x===c.itemType?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></label>'+field('itemName','Item name',c.itemName)+field('contentVersion','Item/content version',c.contentVersion)+field('profile','Game/project profile',c.profile)+field('screen','IKEMaker screen or viewer',c.screen)+field('build','Game build or other version (optional)')+'<label>Severity<select name="severity" style="display:block;width:100%">'+['Untriaged','Low','Medium','High','Critical'].map(x=>'<option>'+x+'</option>').join('')+'</select></label></div><button type="button" id="issueDefinition">Read name/version from definition…</button>'+area('steps','Steps to reproduce')+area('actual','Additional observed result (optional)')+'</details><label>Destination <select name="destination"><option value="ticket" '+(view==='tickets'?'selected':'')+'>Create Bug ticket in Backlog</option><option value="report" '+(view==='reports'?'selected':'')+'>Submit feedback to Report Intake</option></select></label><p class="muted">Board scope: all work projects in this game share one board. Evidence entries are references; files are not uploaded or copied.</p><button type="submit">Save to project</button><button type="reset">Clear form</button></form></details>';
}
let issueProjectFilter=vscode.getState()?.issueProjectFilter||'all';
function inIssueProject(item){return issueProjectFilter==='all'||(issueProjectFilter==='unassigned'?!item.workProjectId:item.workProjectId===issueProjectFilter.slice(3));}
function projectFilterHtml(){const projects=new Map([...data.ticketBoard.tickets,...data.ticketBoard.reports].filter(item=>item.workProjectId).map(item=>[item.workProjectId,item.project||item.workProjectId]));if(data.assignedWorkProject)projects.set(data.assignedWorkProject.id,data.assignedWorkProject.name);const choices=[['all','All work projects in this game'],['unassigned','Legacy / no assigned work project'],...[...projects].map(([id,name])=>['id:'+id,name])];return '<label>Board filter <select id="issueProjectFilter">'+choices.map(([id,label])=>'<option value="'+esc(id)+'" '+(id===issueProjectFilter?'selected':'')+'>'+esc(label)+'</option>').join('')+'</select></label>';}
