const productionHtml = html;
html = (data) => cohesive(productionHtml(data));

function workflowCharacterChoices(seed) {
  const candidates = [], seen = new Set(), add = (filename) => { const resolved = path.resolve(filename || ''); if (!filename || seen.has(resolved.toLowerCase()) || !isCharacterDef(resolved)) return; seen.add(resolved.toLowerCase()); candidates.push(resolved); };
  const starts = [seed?.fsPath, vscode.window.activeTextEditor?.document.fileName, ...(vscode.workspace.workspaceFolders || []).map((folder) => folder.uri.fsPath)].filter(Boolean);
  for (const start of starts) { const root = gameRoot(start); if (root) for (const filename of characterDefs(root)) add(filename); }
  return candidates.sort((a, b) => path.basename(path.dirname(a)).localeCompare(path.basename(path.dirname(b)), undefined, { numeric: true })).map((filename) => ({ label: path.basename(path.dirname(filename)), description: filename, filename }));
}
async function browseCharacterDef(seed) {
  const root = gameRoot(seed?.fsPath || vscode.window.activeTextEditor?.document.fileName || (vscode.workspace.workspaceFolders || [])[0]?.uri.fsPath || '');
  const picked = await vscode.window.showOpenDialog({ title: 'Choose a character DEF', defaultUri: root ? vscode.Uri.file(path.join(root, 'chars')) : undefined, canSelectMany: false, canSelectFiles: true, canSelectFolders: false, filters: { 'Character definition': ['def'] } });
  if (!picked?.[0]) return '';
  if (!isCharacterDef(picked[0].fsPath)) { vscode.window.showWarningMessage('That DEF does not declare character files. Choose the character’s main DEF, not a stage or screenpack DEF.'); return ''; }
  return picked[0].fsPath;
}
async function chooseCharacter(seed) {
  return chooseCharacterDef(seed, { title: 'Production Workflow — Character' });
}
async function saveProgress(state, changes) { const progress = changes(state.progress); await stageWorkflow(state,state.progressPath,progress,state.progressHash); }
async function saveTickets(state, changes) { const board = changes(state.ticketBoard); await stageWorkflow(state,state.ticketPath,board,state.ticketHash); }
async function createTicketPrompt(state, actor, parentId = '') {
  const parent = parentId ? state.ticketBoard.tickets.find((ticket) => ticket.id === parentId) : null;
  const title = await vscode.window.showInputBox({ title: parent ? `New child ticket under ${parent.title}` : 'New project ticket', prompt: 'Use one clear outcome, such as “Build Ryu” or “Correct fireball clashes”.' }); if (!title?.trim()) return false;
  const type = await vscode.window.showQuickPick(parent ? tickets.TYPES.filter((item) => item !== 'Epic') : tickets.TYPES, { title: 'Ticket type', placeHolder: 'Epic contains child tickets; other tickets contain task checklists.' }); if (!type) return false;
  const scope = await vscode.window.showQuickPick([{ label: state.character.name, description: 'Current character' }, { label: 'Project-wide', description: 'Not tied to one character' }], { title: 'Ticket scope' }); if (!scope) return false;
  const description = await vscode.window.showInputBox({ title: 'Ticket description (optional)', prompt: 'State the desired result or acceptance condition. Add the task checklist from the board.' }); if (description === undefined) return false;
  await saveTickets(state, (board) => tickets.createTicket(board, { ...issueProject(state,parentId), title, type, parentId, character: scope.label === 'Project-wide' ? '' : state.character.name, description: description || '', column: type === 'Discussion' ? 'discussion' : 'backlog' }, actor)); return true;
}
